public struct ValidatorCredentials {
    public var authorityPubKey: Base64?
    public var networkPubKey: Base64?
    public var protocolPubKey: Base64?
    public var proofOfPossession: Base64?
    public var netAddress: String?
    public var p2pAddress: String?
    public var primaryAddress: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(authorityPubKey: Base64?, networkPubKey: Base64?, protocolPubKey: Base64?, proofOfPossession: Base64?, netAddress: String?, p2pAddress: String?, primaryAddress: String?) {
        self.authorityPubKey = authorityPubKey
        self.networkPubKey = networkPubKey
        self.protocolPubKey = protocolPubKey
        self.proofOfPossession = proofOfPossession
        self.netAddress = netAddress
        self.p2pAddress = p2pAddress
        self.primaryAddress = primaryAddress
    }
}

#if compiler(>=6)
extension ValidatorCredentials: Sendable {}
#endif


extension ValidatorCredentials: Equatable, Hashable {
    public static func ==(lhs: ValidatorCredentials, rhs: ValidatorCredentials) -> Bool {
        if lhs.authorityPubKey != rhs.authorityPubKey {
            return false
        }
        if lhs.networkPubKey != rhs.networkPubKey {
            return false
        }
        if lhs.protocolPubKey != rhs.protocolPubKey {
            return false
        }
        if lhs.proofOfPossession != rhs.proofOfPossession {
            return false
        }
        if lhs.netAddress != rhs.netAddress {
            return false
        }
        if lhs.p2pAddress != rhs.p2pAddress {
            return false
        }
        if lhs.primaryAddress != rhs.primaryAddress {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(authorityPubKey)
        hasher.combine(networkPubKey)
        hasher.combine(protocolPubKey)
        hasher.combine(proofOfPossession)
        hasher.combine(netAddress)
        hasher.combine(p2pAddress)
        hasher.combine(primaryAddress)
    }
}



