public enum CommandArgumentError {
    
    case typeMismatch
    case invalidBcsBytes
    case invalidUsageOfPureArgument
    case invalidArgumentToPrivateEntryFunction
    case indexOutOfBounds(index: UInt16
    )
    case secondaryIndexOutOfBounds(result: UInt16, subresult: UInt16
    )
    case invalidResultArity(result: UInt16
    )
    case invalidGasCoinUsage
    case invalidValueUsage
    case invalidObjectByValue
    case invalidObjectByMutRef
    case sharedObjectOperationNotAllowed
}


#if compiler(>=6)
extension CommandArgumentError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCommandArgumentError: FfiConverterRustBuffer {
    typealias SwiftType = CommandArgumentError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CommandArgumentError {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .typeMismatch
        
        case 2: return .invalidBcsBytes
        
        case 3: return .invalidUsageOfPureArgument
        
        case 4: return .invalidArgumentToPrivateEntryFunction
        
        case 5: return .indexOutOfBounds(index: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 6: return .secondaryIndexOutOfBounds(result: try FfiConverterUInt16.read(from: &buf), subresult: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 7: return .invalidResultArity(result: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 8: return .invalidGasCoinUsage
        
        case 9: return .invalidValueUsage
        
        case 10: return .invalidObjectByValue
        
        case 11: return .invalidObjectByMutRef
        
        case 12: return .sharedObjectOperationNotAllowed
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CommandArgumentError, into buf: inout [UInt8]) {
        switch value {
        
        
        case .typeMismatch:
            writeInt(&buf, Int32(1))
        
        
        case .invalidBcsBytes:
            writeInt(&buf, Int32(2))
        
        
        case .invalidUsageOfPureArgument:
            writeInt(&buf, Int32(3))
        
        
        case .invalidArgumentToPrivateEntryFunction:
            writeInt(&buf, Int32(4))
        
        
        case let .indexOutOfBounds(index):
            writeInt(&buf, Int32(5))
            FfiConverterUInt16.write(index, into: &buf)
            
        
        case let .secondaryIndexOutOfBounds(result,subresult):
            writeInt(&buf, Int32(6))
            FfiConverterUInt16.write(result, into: &buf)
            FfiConverterUInt16.write(subresult, into: &buf)
            
        
        case let .invalidResultArity(result):
            writeInt(&buf, Int32(7))
            FfiConverterUInt16.write(result, into: &buf)
            
        
        case .invalidGasCoinUsage:
            writeInt(&buf, Int32(8))
        
        
        case .invalidValueUsage:
            writeInt(&buf, Int32(9))
        
        
        case .invalidObjectByValue:
            writeInt(&buf, Int32(10))
        
        
        case .invalidObjectByMutRef:
            writeInt(&buf, Int32(11))
        
        
        case .sharedObjectOperationNotAllowed:
            writeInt(&buf, Int32(12))
        
        }
    }
}


