@_documentation(visibility: private)
#endif
public struct FfiConverterTypeExecutionStatus: FfiConverterRustBuffer {
    typealias SwiftType = ExecutionStatus

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ExecutionStatus {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .success
        
        case 2: return .failure(error: try FfiConverterTypeExecutionError.read(from: &buf), command: try FfiConverterOptionUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ExecutionStatus, into buf: inout [UInt8]) {
        switch value {
        
        
        case .success:
            writeInt(&buf, Int32(1))
        
        
        case let .failure(error,command):
            writeInt(&buf, Int32(2))
            FfiConverterTypeExecutionError.write(error, into: &buf)
            FfiConverterOptionUInt64.write(command, into: &buf)
            
        }
    }
}


